export const HEATSINK_NTC_TASK={"id":"heatsink-ntc","revision":1,"category":2,"title":["ヒートシンクのNTCを交換する","Replace the heatsink NTC","Výměna NTC chladiče","Kühlkörper-NTC austauschen"],"interval":["交換が必要なとき","When replacement is needed","Při potřebě výměny","Bei erforderlichem Austausch"],"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429","steps":[{"title":["作業を始める前に","Before starting","Před zahájením","Vor dem Beginn"],"body":["ヒートシンクの温度を測るNTCサーミスターを交換します。アンロード・完全冷却・電源切断から順に進めます。","Replace the NTC measuring heatsink temperature. Start with unloading, complete cooling and disconnecting power.","Vyměňuje se NTC měřící teplotu chladiče. Začněte vysunutím filamentu, úplným vychladnutím a odpojením napájení.","Der NTC zur Messung der Kühlkörpertemperatur wird ersetzt. Mit Entladen, vollständigem Abkühlen und Trennen der Stromversorgung beginnen."],"refs":[794,806],"number":1,"officialId":931471,"officialStep":2,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931471","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/573269aac3e85d0115317f9781d8d154_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/573269aac3e85d0115317f9781d8d154_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/adceec655e3bc0c57eebee1d5b194a94-533x400.jpg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/adceec655e3bc0c57eebee1d5b194a94.jpg"}]},{"title":["工具を用意する","Prepare the tools","Příprava nástrojů","Werkzeuge bereitlegen"],"body":["2.5 mm六角レンチ、T6、T10を用意します。","Prepare a 2.5 mm hex key, T6 and T10.","Připravte 2,5mm imbus, T6 a T10.","2,5-mm-Innensechskant, T6 und T10 bereitlegen."],"refs":[811],"number":2,"officialId":931506,"officialStep":3,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931506","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/12fd8e02c23f388e_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/12fd8e02c23f388e_painted.jpeg"}]},{"title":["アンロードして冷却する","Unload and cool down","Vysunutí filamentu a ochlazení","Entladen und abkühlen"],"body":["ドアを閉じ、Filament → Unload filamentでアンロードします。スプールを外し、Preheat → COOLDOWNで室温まで冷却します。","Close the door. Use Filament → Unload filament, remove the spool, then select Preheat → COOLDOWN and wait for ambient temperature.","Zavřete dvířka. Zvolte Filament → Unload filament, odeberte cívku a přes Preheat → COOLDOWN vyčkejte na pokojovou teplotu.","Tür schließen. Filament → Unload filament ausführen, Spule abnehmen und über Preheat → COOLDOWN auf Raumtemperatur abkühlen."],"refs":["lcd","hotend"],"firmwareActions":["unload","cooldown"],"number":3,"officialId":931548,"officialStep":4,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931548","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/c766591377a60c5b_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/c766591377a60c5b_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/8281194fc5537bd1_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/8281194fc5537bd1_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/62a2be511d86f736_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/62a2be511d86f736_painted.jpeg"}]},{"title":["ベッドを下げて電源を切る","Lower the bed and disconnect power","Spuštění podložky a odpojení","Heizbett absenken und Netz trennen"],"body":["Control → Move Axis → Move Zで100 mm以上に下げます。停止を待って電源を切り、電源コードを抜きます。","Set Control → Move Axis → Move Z to at least 100 mm. Wait for movement to stop, switch off and unplug.","V Control → Move Axis → Move Z nastavte alespoň 100 mm. Vyčkejte na zastavení, vypněte a odpojte přívod.","Control → Move Axis → Move Z auf mindestens 100 mm stellen. Stillstand abwarten, ausschalten und Netzstecker ziehen."],"refs":["bedSupport","heatbed","sheet","psu"],"action":"lb-bed-down","firmwareActions":["moveZ"],"number":4,"officialId":931610,"officialStep":5,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931610","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/c135ccb88570b265_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/c135ccb88570b265_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/870440f72d7209e3_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/870440f72d7209e3_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/04b56808fb1f0dad_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/04b56808fb1f0dad_painted.jpeg"}]},{"title":["上面カバーを外す","Remove the top cover","Sejmutí horního krytu","Oberen Deckel abnehmen"],"body":["ドアを開き、上面カバーの右前のリベットを内側から押して解除し、外から抜きます。残りのリベットも同様に外し、上面カバーを持ち上げます。","Open the door. Push the front-right top-cover rivet from inside to release it, then remove it from outside. Remove the other rivets in the same way and lift off the cover.","Otevřete dvířka. Pravý přední nýt horního krytu vytlačte zevnitř a vytáhněte zvenku. Stejně vyjměte ostatní nýty a zvedněte kryt.","Tür öffnen. Den Nietenverschluss vorn rechts am oberen Deckel von innen entriegeln und außen herausziehen. Die übrigen Nieten ebenso entfernen und den Deckel abheben."],"refs":[87,"ventBlock"],"action":"lb-top-out","number":5,"officialId":931656,"officialStep":6,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931656","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/000614f52ac70d45_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/000614f52ac70d45_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/f73bb06ea9584d57_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/f73bb06ea9584d57_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/2d54659491f20ef7_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/2d54659491f20ef7_painted.jpeg"}]},{"title":["ヒートベッドを保護する","Protect the heatbed","Ochrana vyhřívané podložky","Heizbett schützen"],"body":["厚手の布などでベッドを覆い、落とした工具や部品で傷を付けないようにします。","Cover the bed with sufficiently thick fabric to protect it from tools and parts.","Podložku zakryjte dostatečně silnou látkou proti poškození nářadím a díly.","Heizbett mit ausreichend dickem Stoff vor Werkzeug und Teilen schützen."],"refs":["heatbed"],"number":6,"officialId":931702,"officialStep":7,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931702","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/74407c871298ff3e_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/74407c871298ff3e_painted.jpeg"}]},{"title":["左カバーを外す","Remove the left cover","Sejmutí levého krytu","Linke Abdeckung abnehmen"],"body":["M3×10を外します。カバーを外側へ開き、下側の掛かりを抜きます。","Remove the M3×10. Open the cover outward and release its lower hook.","Vyšroubujte M3×10. Kryt odklopte ven a uvolněte spodní háček.","M3×10 entfernen. Abdeckung nach außen öffnen und unten aushaken."],"refs":[858,879],"action":"lb-cover-out","number":7,"officialId":931728,"officialStep":8,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931728","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/499d3eb6fbc9d450_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/499d3eb6fbc9d450_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/b14c48359841dc12_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/b14c48359841dc12_painted.jpeg"}]},{"title":["ホットエンドを抜線する","Disconnect the hotend","Odpojení hotendu","Hotend abstecken"],"body":["ラッチを押してヒーター、サーミスターの順に抜きます。配線を引っ張らないでください。","Press the latches and unplug the heater, then the thermistor. Do not pull the wires.","Stiskněte západky a odpojte topení, poté termistor. Netahejte za vodiče.","Verriegelungen drücken und Heizung, dann Thermistor abstecken. Nicht an Leitungen ziehen."],"refs":["hotendHeater0","hotendThermistor0","loveBoard"],"action":"lb-hotend-unplug","number":8,"officialId":931764,"officialStep":9,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931764","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/c69db7e60c548fea_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/c69db7e60c548fea_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/f515433880dfad87_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/f515433880dfad87_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/5692168e58e0a08e_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/5692168e58e0a08e_painted.jpeg"}]},{"title":["ホットエンドを支えて抜く","Support and withdraw the hotend","Podepření a vyjmutí hotendu","Hotend halten und herausziehen"],"body":["ケーブルをガイドから外し、ホットエンドを手で支えます。つまみネジ2本を数回転緩め、ヒートシンクから下へ抜きます。ネジは抜き切りません。","Free the cables from the guide and support the hotend. Loosen both thumbscrews a few turns and withdraw downward. Keep the screws in place.","Uvolněte kabely z vedení a hotend podepřete. Oba ruční šrouby povolte o několik otáček a hotend vysuňte dolů. Šrouby nevyjímejte.","Kabel aus der Führung lösen und Hotend halten. Beide Rändelschrauben einige Umdrehungen lockern und Hotend nach unten ziehen. Schrauben nicht ganz entfernen."],"refs":["hotend",795,807],"action":"lb-hotend-out","number":9,"officialId":931802,"officialStep":10,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931802","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/6c4bd39b97902d95_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/6c4bd39b97902d95_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/240a3ef257c75a4e_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/240a3ef257c75a4e_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/4e48aadedaf72418_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/4e48aadedaf72418_painted.jpeg"}]},{"title":["左側と上面の配線を抜く","Disconnect left and top leads","Odpojení levých a horních kabelů","Linke und obere Leitungen lösen"],"body":["各コネクターの解除バーを指の腹で押し、ロックを外してからまっすぐ抜きます。プリントファンの配線を後ろへ逃がし、上面のモーター、ヒートシンクのNTC、ホットエンドファンの順に外します。","Unplug the print fan and move its lead back. Disconnect the top motor, heatsink NTC and hotend fan.","Odpojte tiskový ventilátor a kabel odsuňte dozadu. Odpojte horní motor, NTC chladiče a ventilátor hotendu.","Drucklüfter abstecken und Kabel nach hinten legen. Motor oben, Kühlkörper-NTC und Hotend-Lüfter abstecken."],"refs":["loveBoard","lbMotorLead","lbNtcLead","servicePrintLead","serviceHotendFanLead"],"action":"lb-left-unplug","number":10,"officialId":931856,"officialStep":11,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931856","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/acd1e3ae41f217fb_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/acd1e3ae41f217fb_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/b21daa9993e39f3f_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/b21daa9993e39f3f_painted.jpeg"}]},{"title":["右カバーとセンサー配線を外す","Remove right cover and sensor leads","Pravý kryt a kabely senzorů","Rechte Abdeckung und Sensorkabel lösen"],"body":["右側のM3×6を2本外してカバーを外します。ロードセル、フィラメントセンサーの順に、解除バーを押してロックを外し、まっすぐ抜きます。","Remove the two right-side M3×6 screws and cover. Unplug the loadcell and filament sensor.","Vyjměte dva pravé šrouby M3×6 a kryt. Odpojte loadcell a senzor filamentu.","Zwei rechte M3×6 und Abdeckung entfernen. Wägezelle und Filamentsensor abstecken."],"refs":["ventLever",870,872,"lbLoadcellLead","lbFilamentLead"],"action":"lb-right-out","number":11,"officialId":931892,"officialStep":12,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931892","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/a8d61ed1d9d34ae19bd975924d2eb856_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/a8d61ed1d9d34ae19bd975924d2eb856_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/59eeddda9827d14dcee537ec245959ad_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/59eeddda9827d14dcee537ec245959ad_painted.jpeg"}]},{"title":["ホットエンドファンを外す","Remove the hotend fan","Demontáž ventilátoru hotendu","Hotend-Lüfter ausbauen"],"body":["M3×18を2本外し、ヒートシンクからファンを外します。","Remove both M3×18 screws and lift the fan away from the heatsink.","Vyjměte oba šrouby M3×18 a sejměte ventilátor z chladiče.","Beide M3×18 entfernen und Lüfter vom Kühlkörper abnehmen."],"refs":[791,819,821],"action":"lb-hotfan-out","number":12,"officialId":931920,"officialStep":13,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931920","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/40ffeff5511f828b_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/40ffeff5511f828b_painted.jpeg"}]},{"title":["Nextruderを外す","Remove the Nextruder","Demontáž Nextruderu","Nextruder ausbauen"],"body":["正面のM3×10を3本外します。Nextruderを支えて上のPTFE継手を緩め、ゆっくり取り外します。NTCの配線をキャリッジのフックから外し、引っ掛けないでください。","Remove the three front M3×10 screws. Support the Nextruder, unscrew the top PTFE fitting and withdraw slowly. Release the NTC lead from the carriage hook.","Vyjměte tři přední M3×10. Nextruder podepřete, vyšroubujte horní PTFE šroubení a pomalu jej sejměte. Kabel NTC uvolněte z háčku vozíku.","Drei vordere M3×10 entfernen. Nextruder halten, obere PTFE-Verschraubung lösen und langsam abnehmen. NTC-Leitung aus dem Wagenhaken lösen."],"refs":[788,"lbNtcLead"],"action":"lb-nextruder-out","number":13,"officialId":931938,"officialStep":14,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931938","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/4fe86484e38185d82aa7ea920cdff8d3_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/4fe86484e38185d82aa7ea920cdff8d3_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/f4b27cd5b87911ba7c6a4ea1241b566f_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/f4b27cd5b87911ba7c6a4ea1241b566f_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/d2d0009e4ff83944b1f72bf8dcc2a8e2_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/d2d0009e4ff83944b1f72bf8dcc2a8e2_painted.jpeg"}]},{"title":["本体を裏返し、NTCを外す","Turn the body and remove the NTC","Otočte tělo a vyjměte NTC","Gehäuse drehen und NTC ausbauen"],"body":["取り外したNextruderを、止めねじが見える向きに返します。T6の短辺でM3x4Tを外し、ヒートシンクのNTCを引き抜きます。","Turn the detached Nextruder to expose the grub screw. Use the short side of T6 to remove M3x4T, then withdraw the heatsink NTC.","Vyjmutý Nextruder otočte tak, aby byl přístupný stavěcí šroub. Krátkou stranou T6 vyjměte M3x4T a vytáhněte NTC z chladiče.","Den ausgebauten Nextruder so drehen, dass die Madenschraube zugänglich ist. M3x4T mit der kurzen T6-Seite entfernen, dann den Kühlkörper-NTC herausziehen."],"refs":[794,806,811,"lbNtcLead"],"action":"ntc-bench-out","number":14,"officialId":931976,"officialStep":15,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#931976","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/d50e48e48918af3634c280844b9e344a_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/d50e48e48918af3634c280844b9e344a_painted.jpeg"}]},{"title":["交換するNTCと止めねじを用意する","Prepare the NTC and grub screw","Připravte NTC a stavěcí šroub","NTC und Madenschraube vorbereiten"],"body":["ヒートシンク用NTCサーミスター90 mmを1個、M3x4Tを1本用意します。ヒーターブロック用サーミスターとは別の部品です。","Prepare one 90 mm heatsink NTC and one M3x4T. This is a different component from the heater-block thermistor.","Připravte jeden NTC chladiče 90 mm a jeden M3x4T. Nejde o termistor topného bloku.","Einen 90-mm-Kühlkörper-NTC und eine M3x4T bereitlegen. Das ist ein anderes Bauteil als der Thermistor im Heizblock."],"refs":[806,811,"lbNtcLead"],"inspection":true,"number":15,"officialId":932602,"officialStep":16,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932602","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/03/966562f8d45414715c4354d6e49873c3_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/03/966562f8d45414715c4354d6e49873c3_painted.jpeg"}]},{"title":["NTCを差し込み、止めねじを締める","Insert the NTC and secure it","Zasuňte NTC a zajistěte jej","NTC einsetzen und sichern"],"body":["モーター側からヒートシンクの穴へNTCを差し込みます。T6の短辺を2本の指で持ち、M3x4Tを慎重に締めて固定します。締めすぎるとセンサーやねじ穴を傷めます。","Insert the NTC into the heatsink from the motor side. Hold the short side of T6 with two fingers and secure M3x4T gently but firmly. Overtightening can damage the sensor or threads.","NTC zasuňte do chladiče ze strany motoru. Krátkou stranu T6 držte dvěma prsty a M3x4T dotáhněte jemně, ale pevně. Přetažení může poškodit snímač nebo závit.","Den NTC von der Motorseite in den Kühlkörper einsetzen. Die kurze T6-Seite mit zwei Fingern halten und M3x4T vorsichtig, aber fest anziehen. Zu starkes Anziehen kann Sensor oder Gewinde beschädigen."],"refs":[794,806,811,"lbNtcLead"],"action":"ntc-bench-in","number":16,"officialId":932012,"officialStep":17,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932012","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/b0e5c56e544c6d3dd7669352879b79d8_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/b0e5c56e544c6d3dd7669352879b79d8_painted.jpeg"}]},{"title":["Nextruderを戻す","Refit the Nextruder","Montáž Nextruderu","Nextruder montieren"],"body":["NTCの配線をキャリッジのフックへ通します。ヒートシンク裏で挟まず、Nextruderを合わせてPTFE継手で保持します。正面のM3×10を3本締めます。","Guide the NTC lead through the carriage hook, clear of the heatsink rear. Align the Nextruder, retain it with the PTFE fitting and secure three front M3×10 screws.","Kabel NTC veďte háčkem vozíku mimo zadní stranu chladiče. Nextruder srovnejte, přidržte PTFE šroubením a upevněte třemi předními M3×10.","NTC-Kabel durch den Wagenhaken führen, nicht hinter dem Kühlkörper einklemmen. Nextruder ausrichten, mit PTFE-Verschraubung halten und drei vordere M3×10 befestigen."],"refs":[788,"lbNtcLead"],"action":"lb-nextruder-in","number":17,"officialId":932048,"officialStep":18,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932048","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/b6bd692a1b0a5a25_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/b6bd692a1b0a5a25_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/2df76ccd447da730_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/2df76ccd447da730_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/26314d3eed6489b7_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/26314d3eed6489b7_painted.jpeg"}]},{"title":["ホットエンドファンを戻す","Refit the hotend fan","Montáž ventilátoru hotendu","Hotend-Lüfter montieren"],"body":["銀色ラベルをヒートシンク側、配線を左へ向けます。M3×18を2本使って固定します。","Face the silver label toward the heatsink and the cable left. Secure with two M3×18 screws.","Stříbrný štítek směřuje k chladiči a kabel doleva. Upevněte dvěma M3×18.","Silbernes Etikett zum Kühlkörper und Kabel nach links ausrichten. Mit zwei M3×18 befestigen."],"refs":[791,819,821],"action":"lb-hotfan-in","number":18,"officialId":932102,"officialStep":19,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932102","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/b6cb6ea13e1f9885_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/b6cb6ea13e1f9885_painted.jpeg"}]},{"title":["右側センサーを接続する","Reconnect right-side sensors","Připojení pravých senzorů","Rechte Sensoren anschließen"],"body":["ロードセルとフィラメントセンサーを接続します。右カバーを戻し、M3×6を2本締めます。","Connect the loadcell and filament sensor. Refit the right cover with two M3×6 screws.","Připojte loadcell a senzor filamentu. Pravý kryt připevněte dvěma M3×6.","Wägezelle und Filamentsensor anschließen. Rechte Abdeckung mit zwei M3×6 montieren."],"refs":["ventLever","lbLoadcellLead","lbFilamentLead"],"action":"lb-right-in","number":19,"officialId":932136,"officialStep":20,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932136","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/e4181602aba3f1cf_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/e4181602aba3f1cf_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/8c09bc801ac001e0_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/8c09bc801ac001e0_painted.jpeg"}]},{"title":["モーター・NTC・ファンを接続する","Connect motor, NTC and fan","Motor, NTC a ventilátor","Motor, NTC und Lüfter anschließen"],"body":["上のモーター端子を接続します。左の内側寄りにNTC、左下にヒートシンクファンを接続します。","Connect the motor on top. Connect the heatsink NTC to the inner left port and the heatsink fan to the lower left port.","Připojte motor nahoře. NTC chladiče patří do vnitřního levého portu a ventilátor chladiče do dolního levého portu.","Motor oben anschließen. Kühlkörper-NTC an den inneren linken, Kühlkörperlüfter an den unteren linken Anschluss stecken."],"refs":["lbMotorLead","lbNtcLead","serviceHotendFanLead","loveBoard"],"action":"lb-left-plug","number":20,"officialId":932164,"officialStep":21,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932164","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/0695306526a93c36_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/0695306526a93c36_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/baf600429ddafc3de90832062008e70d-533x400.jpg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/baf600429ddafc3de90832062008e70d.jpg"}]},{"title":["プリントファンを接続する","Connect the print fan","Připojení tiskového ventilátoru","Drucklüfter anschließen"],"body":["ケーブルをカバーの溝へ通します。配線スペースでループを作り、LoveBoard左側の中央端子へ差し込みます。","Route the lead through the cover channel. Form a loop in the cable area and plug it into the middle left LoveBoard connector.","Kabel veďte kanálem krytu. V prostoru pro kabely vytvořte smyčku a připojte prostřední levý konektor LoveBoardu.","Kabel im Abdeckungskanal führen. Im Kabelraum eine Schlaufe bilden und in den mittleren linken LoveBoard-Anschluss stecken."],"refs":["servicePrintLead",833,"loveBoard"],"action":"lb-print-plug","number":21,"officialId":932199,"officialStep":22,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932199","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/12a4ae5cb8246a44_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/12a4ae5cb8246a44_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/3a1e60844c63da4e3ee210c9385af423_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/3a1e60844c63da4e3ee210c9385af423_painted.jpeg"}]},{"title":["ホットエンドを差し込む","Insert the hotend","Zasunutí hotendu","Hotend einsetzen"],"body":["ケーブルを少し斜め前へ向け、ホットエンドを奥まで上へ押し込みます。ファンシュラウドのくぼみに収まり、周囲に隙間があることを確認します。押し上げたままつまみネジ2本を締めます。ホットエンドはシュラウドの下へ突き出さない位置に合わせます。","Point the cables slightly forward and fully push the hotend upward into the heatsink. Check that it sits in the fan-shroud recess with clearance around it. Keep pushing upward while tightening both thumbscrews. The hotend must not protrude below the shroud.","Kabely natočte mírně dopředu a hotend zcela zasuňte vzhůru do chladiče. Musí zapadnout do vybrání krytu ventilátoru s volným prostorem kolem. Při dotahování obou ručních šroubů jej stále tlačte nahoru. Nesmí vyčnívat pod kryt.","Kabel leicht nach vorn ausrichten und das Hotend vollständig nach oben in den Kühlkörper schieben. Es muss mit Abstand zur Umgebung in der Aussparung der Lüfterdüse sitzen. Beim Festziehen beider Rändelschrauben weiter nach oben drücken. Das Hotend darf nicht unter der Lüfterdüse hervorstehen."],"refs":["hotend",795,807],"action":"lb-hotend-in","number":22,"officialId":932227,"officialStep":23,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932227","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/60b4d272dff19cec_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/60b4d272dff19cec_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/a16ec16166ee0ad8_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/a16ec16166ee0ad8_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/d57720a82490f6bd_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/d57720a82490f6bd_painted.jpeg"}]},{"title":["ノズルの挿入を確認する","Check nozzle seating","Kontrola zasunutí trysky","Düsensitz prüfen"],"body":["銅色のリングが見えない位置まで挿入できているか確認します。挿入が浅いと熱が十分に伝わらず、詰まりの原因になります。リングが見える場合はつまみネジを緩め、ホットエンドを押し上げながら締め直します。","Check that the copper ring is hidden inside the heatsink. Incomplete insertion reduces heat transfer and can cause clogs. If the ring is visible, loosen the thumbscrews, push the hotend upward and retighten them while holding it up.","Zkontrolujte, že měděný kroužek není vidět. Neúplné zasunutí zhoršuje přenos tepla a může způsobit ucpání. Pokud je kroužek vidět, povolte ruční šrouby, hotend zatlačte vzhůru a v této poloze je znovu dotáhněte.","Prüfen, dass der Kupferring im Kühlkörper verborgen ist. Unvollständiges Einsetzen verschlechtert die Wärmeübertragung und kann Verstopfungen verursachen. Bei sichtbarem Ring die Rändelschrauben lösen, das Hotend nach oben drücken und so gehalten wieder festziehen."],"refs":["hotend",794],"number":23,"officialId":932281,"officialStep":24,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932281","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/09b9d8a9637ba2a7_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/09b9d8a9637ba2a7_painted.jpeg"}]},{"title":["ケーブルをガイドへ通す","Route the hotend leads","Vedení kabelů hotendu","Hotend-Leitungen führen"],"body":["つまみネジの後ろのフックへ、サーミスター、ヒーターの順に通します。","Route the thermistor first, then the heater, through the hook behind the thumbscrews.","Háčkem za ručními šrouby veďte nejprve termistor a potom topení.","Erst Thermistor, dann Heizung durch den Haken hinter den Rändelschrauben führen."],"refs":["hotendThermistor0","hotendHeater0",857],"action":"lb-hotend-route","number":24,"officialId":932315,"officialStep":25,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932315","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/b2d220621a430434_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/b2d220621a430434_painted.jpeg"}]},{"title":["ホットエンドを接続する","Connect the hotend","Připojení hotendu","Hotend anschließen"],"body":["サーミスターをLoveBoard左上の端子、ヒーターを上部の黒い端子へ接続します。","Connect the thermistor to the upper left slot and the heater to the black upper socket.","Termistor připojte do levé horní zdířky, topení do horního černého konektoru.","Thermistor oben links und Heizung an die schwarze obere Buchse anschließen."],"refs":["hotendThermistor0","hotendHeater0","loveBoard"],"action":"lb-hotend-plug","number":25,"officialId":932333,"officialStep":26,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932333","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/432b2a7892e5b33a_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/432b2a7892e5b33a_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/94cf94a52821bf63_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/94cf94a52821bf63_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/bd700ef6282c7218_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/bd700ef6282c7218_painted.jpeg"}]},{"title":["左カバーを戻す","Refit the left cover","Nasazení levého krytu","Linke Abdeckung montieren"],"body":["配線を内側へ収め、下側を先に掛けます。Nextruder側へ閉じ、M3×10で固定します。ベッドの保護材を外します。","Tuck the wires inside. Hook the bottom first, close toward the Nextruder and secure with M3×10. Remove the bed protection.","Vodiče uložte dovnitř. Nejprve zahákněte spodní část, kryt přitlačte k Nextruderu a zajistěte M3×10. Odstraňte ochranu podložky.","Leitungen innen verstauen. Unten einhaken, zum Nextruder schließen und mit M3×10 befestigen. Heizbettschutz entfernen."],"refs":[858,879],"action":"lb-cover-in","number":26,"officialId":932363,"officialStep":27,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932363","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/5b0cabe02085c037_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/5b0cabe02085c037_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/700d9d6d5ea4fd8c_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/700d9d6d5ea4fd8c_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/2644d4ba20bff318_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/2644d4ba20bff318_painted.jpeg"}]},{"title":["上面カバーを戻す","Refit the top cover","Nasazení horního krytu","Oberen Deckel montieren"],"body":["右奥のフレームと前側のくぼみに合わせます。公式写真の位置にナイロンリベット2本で固定します。","Align with the rear right frame and front recess. Secure with two nylon rivets at the positions in the official photo.","Srovnejte s pravým zadním rámem i předním vybráním. Upevněte dvěma nylonovými nýty podle oficiální fotografie.","An hinterem rechten Rahmen und vorderer Aussparung ausrichten. Mit zwei Nylonnieten gemäß offiziellem Foto befestigen."],"refs":[87,"ventBlock"],"action":"lb-top-in","number":27,"officialId":932425,"officialStep":28,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932425","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/2bc8f3412b9ff7f6_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/2bc8f3412b9ff7f6_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/67e805e244292751_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/67e805e244292751_painted.jpeg"}]},{"title":["電源を入れる","Power on","Zapnutí tiskárny","Drucker einschalten"],"body":["ドアを閉じ、電源コードを接続して電源を入れます。","Close the door, reconnect power and switch on.","Zavřete dvířka, připojte napájení a zapněte tiskárnu.","Tür schließen, Netzkabel anschließen und einschalten."],"refs":["psu","lcd"],"number":28,"officialId":932469,"officialStep":29,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932469","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/c206f1d5db866ece_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/c206f1d5db866ece_painted.jpeg"},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/69882cbd3eb87945_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/69882cbd3eb87945_painted.jpeg"}]},{"title":["Selftestを実行する","Run the Selftest","Spuštění Selftestu","Selbsttest ausführen"],"body":["Control → Calibrations & TestsでSelftestを実行し、必ずギアボックス調整も行います。Nextruderを組み立て・整備・開閉した後は、遊星ギアの位置合わせが必要です。省略すると異音、フィラメントの削れ、押し出しのむらが起きることがあります。画面の案内に従い、必要なテストがすべて緑のチェックになってから使用を再開します。","Run Selftest under Control → Calibrations & Tests and complete Gearbox Alignment. Planetary gears must be aligned after assembling, servicing or opening the Nextruder. Skipping this can cause ticking, filament grinding and uneven extrusion. Follow the display and resume use only after all required tests show green checks.","Spusťte Selftest v Control → Calibrations & Tests a proveďte také Gearbox Alignment. Po sestavení, servisu nebo otevření Nextruderu je nutné vyrovnat planetová kola. Vynechání může způsobit cvakání, obrušování filamentu a nerovnoměrnou extruzi. Řiďte se displejem a pokračujte až po zeleném potvrzení všech potřebných testů.","Selftest unter Control → Calibrations & Tests und auch Gearbox Alignment ausführen. Nach Montage, Wartung oder Öffnen des Nextruders müssen die Planetenräder ausgerichtet werden. Andernfalls können Ticken, abgeschliffenes Filament und ungleichmäßige Extrusion auftreten. Der Anzeige folgen und erst nach grünen Häkchen bei allen erforderlichen Tests weiterarbeiten."],"refs":["lcd"],"firmwareActions":["selftest"],"number":29,"officialId":932575,"officialStep":30,"source":"https://help.prusa3d.com/guide/how-to-replace-heatsink-ntc-thermistor-core-one_922429#932575","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/08/a12ccb012299f351_painted-533x400.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/08/a12ccb012299f351_painted.jpeg"}]}]};
